shared_html.shared_css:
/* ---------- shared header ---------- */
.site-nav {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, sans-serif;
  position: relative;
}
.site-nav__inner {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 3rem;
  padding: 1.75rem clamp(1.25rem, 4vw, 3.5rem) 1.25rem;
  max-width: 1320px;
  margin: 0 auto;
}
.site-nav__brand {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  text-decoration: none;
  color: var(--primary);
}
.site-nav__mark {
  display: inline-flex;
  color: var(--accent);
}
.site-nav__wordmark {
  display: flex;
  flex-direction: column;
  line-height: 1.05;
}
.site-nav__name {
  font-family: 'Shippori Mincho', serif;
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: 0.01em;
}
.site-nav__sub {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin-top: 0.35rem;
  font-weight: 400;
}
.site-nav__links {
  display: flex;
  gap: 1.85rem;
  flex-wrap: wrap;
  align-items: baseline;
}
.site-nav__links a {
  color: var(--primary);
  text-decoration: none;
  font-size: 0.84rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  display: inline-flex;
  align-items: baseline;
  gap: 0.45rem;
  padding-bottom: 0.25rem;
  border-bottom: 1px solid transparent;
  transition: border-color 160ms ease, color 160ms ease;
}
.site-nav__links a:hover {
  border-bottom-color: var(--accent);
  color: var(--text-emphasis);
}
.site-nav__num {
  font-family: 'Shippori Mincho', serif;
  font-size: 0.7rem;
  color: var(--accent);
  letter-spacing: 0;
}
.site-nav__rule {
  height: 1px;
  background: var(--ornament);
  opacity: 0.85;
  max-width: 1320px;
  margin: 0 auto;
  width: calc(100% - clamp(2.5rem, 8vw, 7rem));
}
.site-nav__rule::after {
  content: "";
  display: block;
  height: 4px;
  margin-top: 6px;
  background-image: radial-gradient(circle at 4px 2px, var(--ornament) 0.6px, transparent 1.2px);
  background-size: 14px 4px;
  opacity: 0.35;
}
@media (max-width: 760px) {
  .site-nav__inner {
    flex-direction: column;
    align-items: flex-start;
    gap: 1.25rem;
  }
  .site-nav__links { gap: 1.1rem; }
}

/* ---------- shared footer ---------- */
.site-footer {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, sans-serif;
  margin-top: 6rem;
  position: relative;
}
.site-footer__rule {
  height: 1px;
  background: var(--ornament);
  max-width: 1320px;
  margin: 0 auto;
  width: calc(100% - clamp(2.5rem, 8vw, 7rem));
  opacity: 0.9;
}
.site-footer__inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 3.5rem clamp(1.25rem, 4vw, 3.5rem) 2rem;
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr 0.8fr;
  gap: 3rem;
}
.site-footer__col h4 {
  font-family: 'Shippori Mincho', serif;
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin: 0 0 1.1rem;
}
.site-footer__col p {
  font-size: 0.86rem;
  line-height: 1.75;
  margin: 0 0 1rem;
  color: var(--text);
}
.site-footer__col--seal {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.site-footer__seal {
  color: var(--accent);
}
.site-footer__signature {
  font-family: 'Shippori Mincho', serif;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--primary);
}
.site-footer__signature span {
  display: inline-block;
  font-size: 0.72rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin-top: 0.35rem;
}
.site-footer__nav {
  display: flex;
  flex-direction: column;
}
.site-footer__nav a {
  color: var(--primary);
  text-decoration: none;
  font-size: 0.86rem;
  padding: 0.25rem 0;
  border-bottom: 1px solid transparent;
  width: max-content;
  transition: border-color 160ms ease;
}
.site-footer__nav a:hover { border-bottom-color: var(--accent); }
.site-footer__base {
  border-top: 1px solid color-mix(in srgb, var(--ornament) 25%, transparent);
  max-width: 1320px;
  margin: 0 auto;
  padding: 1.4rem clamp(1.25rem, 4vw, 3.5rem) 2.5rem;
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  font-size: 0.74rem;
  color: var(--text-emphasis);
  letter-spacing: 0.04em;
}
.site-footer__base p { margin: 0; }
.site-footer__attr { opacity: 0.75; }
@media (max-width: 880px) {
  .site-footer__inner {
    grid-template-columns: 1fr 1fr;
    gap: 2.25rem;
  }
}
@media (max-width: 520px) {
  .site-footer__inner { grid-template-columns: 1fr; }
}
